// W_Input_Start — Prep Signature. Identical Slack auth as W_Batch_Start / W_Abort, for the
// SLASH COMMAND POST (/go). Slack signs every request:
//   signature = 'v0=' + HMAC_SHA256(signing_secret, `v0:{ts}:{raw_body}`)
// so we hash the EXACT raw body bytes — the webhook has Raw Body = ON (body arrives binary).
const cfg = {};
$('Read Config').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });
const secret = (cfg.slack_signing_secret || '').toString();

const wh = $('Slash Command Webhook').first() || {};
const headers = (wh.json && wh.json.headers) || {};
const given_sig = (headers['x-slack-signature'] || headers['X-Slack-Signature'] || '').toString();
const ts = (headers['x-slack-request-timestamp'] || headers['X-Slack-Request-Timestamp'] || '').toString();

let raw = '';
const b = wh.binary;
if (b && b.data && b.data.data) {
  raw = Buffer.from(b.data.data, 'base64').toString('utf8');
} else if (typeof (wh.json && wh.json.body) === 'string') {
  raw = wh.json.body;
}

const field = (name) => {
  const m = raw.match(new RegExp('(?:^|&)' + name + '=([^&]*)'));
  if (!m) return '';
  try { return decodeURIComponent(m[1].replace(/\+/g, ' ')); } catch (e) { return m[1]; }
};

return [{ json: { base: `v0:${ts}:${raw}`, secret, given_sig, ts, command: field('command'), slack_user: field('user_name') } }];

// W_Input_Start — Verify the Slack slash-command signature. Security gate for the public POST
// webhook: anything that fails verification returns [] (the run is not fired). Same HMAC compare
// + 5-min replay guard as W_Abort / W_Batch_Start.
const prep = $('Prep Signature').first().json || {};
const computed = ($json.computed_sig || '').toString();
const given = (prep.given_sig || '').toString();
const tsNum = Number(prep.ts);
const now = Math.floor(Date.now() / 1000);

if (!prep.secret) { console.warn('W_Input_Start: slack_signing_secret missing from config — rejecting'); return []; }
if (!given || !computed) { console.warn('W_Input_Start: missing signature/hash — rejecting'); return []; }
if (!tsNum || Math.abs(now - tsNum) > 300) { console.warn('W_Input_Start: stale or invalid timestamp — rejecting (replay guard)'); return []; }

const expected = 'v0=' + computed;
if (expected.length !== given.length || expected !== given) { console.warn('W_Input_Start: Slack signature mismatch — rejecting'); return []; }

console.log(`W_Input_Start: verified /go from ${prep.slack_user || 'unknown'}`);
return [{ json: { ok: true, slack_user: prep.slack_user } }];

// Build the Drive files.list query for 01_input/ from config.
const cfg = {};
$('Read Config').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });
const input_folder = (cfg.drive_input_folder_id || '').toString().trim();
if (!input_folder) throw new Error('drive_input_folder_id is not set in config');
const q = "'" + input_folder + "' in parents and trashed = false and mimeType != 'application/vnd.google-apps.folder'";
return [{ json: { q, input_folder, slack_channel: cfg.slack_channel || '' } }];

// Pick the SINGLE newest file in 01_input/ (the one the operator just dropped) and hand it to
// W_Master as a specific file — so only its id goes into new_file_ids and W_Master archives any
// OLDER leftover automatically (same self-cleaning as /batch).
// Guard: if two+ files were dropped at nearly the same time, refuse — that's a /batch job;
// picking one would archive the other unprocessed.
const files = ($json.files) || [];
const prep = $('Prep Input Query').first().json || {};
const emit = (o) => { o.slack_channel = prep.slack_channel; return [{ json: o }]; };

if (files.length === 0) return emit({ status: 'empty' });

const ts = (f) => Date.parse(f.modifiedTime || '') || 0;
const sorted = files.slice().sort((a, b) => ts(b) - ts(a));
const newest = sorted[0];

const AMBIGUOUS_GAP_MS = 120000; // 2 min — files dropped this close together are treated as a batch
if (sorted.length >= 2 && (ts(newest) - ts(sorted[1])) < AMBIGUOUS_GAP_MS) {
  return emit({ status: 'ambiguous', count: files.length });
}

return emit({ status: 'process', id: newest.id, name: newest.name, mimeType: newest.mimeType });

// No single newest file to run: tell the operator why (empty input, or several fresh files).
const j = $json;
const channel = j.slack_channel;
if (!channel) return [];
let text;
if (j.status === 'ambiguous') {
  text = ':warning: /go: у 01_input кілька свіжих файлів — лиши один і повтори, або клади всі в Batch/ і тисни /batch.';
} else {
  text = ':information_source: /go: у 01_input немає файлів — поклади файл і повтори.';
}
return [{ json: { channel, text } }];
